import React, { useState } from 'react';
import './Kanban.css';

const Kanban = () => {
  const [tasks, setTasks] = useState([
    { id: 1, title: 'Analisar pedido', status: 'a-fazer', priority: 'alta' },
    { id: 2, title: 'Separar produtos', status: 'em-andamento', priority: 'media' },
    { id: 3, title: 'Gerar etiqueta', status: 'em-andamento', priority: 'baixa' },
    { id: 4, title: 'Embalar produtos', status: 'feito', priority: 'media' },
    { id: 5, title: 'Enviar para transporte', status: 'feito', priority: 'alta' }
  ]);

  const [draggedTask, setDraggedTask] = useState(null);

  const columns = [
    { id: 'a-fazer', title: 'A Fazer', color: '#ff6b6b' },
    { id: 'em-andamento', title: 'Em Andamento', color: '#4ecdc4' },
    { id: 'feito', title: 'Feito', color: '#45b7d1' }
  ];

  const handleDragStart = (task) => {
    setDraggedTask(task);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = (e, columnId) => {
    e.preventDefault();
    if (draggedTask) {
      setTasks(tasks.map(task => 
        task.id === draggedTask.id 
          ? { ...task, status: columnId }
          : task
      ));
      setDraggedTask(null);
    }
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'alta': return '#ff4757';
      case 'media': return '#ffa502';
      case 'baixa': return '#2ed573';
      default: return '#747d8c';
    }
  };

  const addTask = () => {
    const newTask = {
      id: tasks.length + 1,
      title: `Nova tarefa ${tasks.length + 1}`,
      status: 'a-fazer',
      priority: 'media'
    };
    setTasks([...tasks, newTask]);
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter(task => task.id !== taskId));
  };

  return (
    <div className="kanban-container">
      <div className="kanban-header">
        <h2>Kanban de Processos</h2>
        <button className="add-task-btn" onClick={addTask}>
          + Nova Tarefa
        </button>
      </div>

      <div className="kanban-board">
        {columns.map(column => (
          <div
            key={column.id}
            className="kanban-column"
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, column.id)}
          >
            <div className="column-header" style={{ backgroundColor: column.color }}>
              <h3>{column.title}</h3>
              <span className="task-count">
                {tasks.filter(task => task.status === column.id).length}
              </span>
            </div>

            <div className="column-content">
              {tasks
                .filter(task => task.status === column.id)
                .map(task => (
                  <div
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={() => handleDragStart(task)}
                  >
                    <div className="task-header">
                      <span 
                        className="priority-badge"
                        style={{ backgroundColor: getPriorityColor(task.priority) }}
                      >
                        {task.priority.toUpperCase()}
                      </span>
                      <button 
                        className="delete-btn"
                        onClick={() => deleteTask(task.id)}
                      >
                        ×
                      </button>
                    </div>
                    <div className="task-content">
                      <p>{task.title}</p>
                    </div>
                  </div>
                ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Kanban;
